import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"鹹","description":"周易集解 - 鹹","frontmatter":{"title":"鹹","description":"周易集解 - 鹹"},"headers":[],"relativePath":"classics/jijie/031.md","filePath":"classics/jijie/031.md"}'),l={name:"classics/jijie/031.md"};function n(d,a,t,p,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="鹹" tabindex="-1">鹹 <a class="header-anchor" href="#鹹" aria-label="Permalink to “鹹”">​</a></h1><h2 id="鹹-1" tabindex="-1">鹹 <a class="header-anchor" href="#鹹-1" aria-label="Permalink to “鹹”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>鹹，亨，利貞，取女吉。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：有天地然後有萬物，有萬物然後有男女，有男女然後有夫婦，有夫婦然後有父子，有父子然後有君臣，有君臣然後有上下，有上下然後禮義有所錯。</p><p>韓康伯曰：言鹹卦之義也。鹹柔上而剛下，感應以相與。夫婦之象，莫美乎斯。人倫之道，莫大夫婦。故夫子殷懃深述其義，以崇人倫之始，而不係之離也。先儒以乾至離為上經，天道也；鹹至未濟為下經，人事也。夫易六畫成卦，三材必備，錯綜天人，以效變化，豈有天道人事偏於上下哉。斯蓋守文而不求義，失之遠矣。</p><p>虞翻曰：鹹，感也。坤三之上成女，乾上之三成男，乾坤氣交以相與。止而說，男下女。故｢通利貞，取女吉｣。</p><p>鄭玄曰：鹹，感也。艮為山。兌為澤。山氣下，澤氣上，二氣通而相應，以生萬物，故曰鹹也。其於人也。嘉會禮通，和順於義，幹事能正。三十之男，有此三德，以下二十之女，正而相親說，取之則吉也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：鹹，感也。柔上而剛下，二氣感應以相與。止而說，男下女，是以亨利貞，取女吉也。天地感而萬物化生，聖人感人心而天下和平。觀其所感，而天地萬物之情可見矣。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>蜀才曰：此本否卦。案：六三升上，上九降三，是柔上而剛下，二氣交感，以相與也。</p><p>王肅曰：山澤以氣通，男女以禮感。男而下女，初婚之所以為禮也。通義正，取女之所以為吉也。</p><p>荀爽曰：乾下感坤，故萬物化生於山澤。</p><p>陸績曰：天地因山澤孔竅，以通其氣，化生萬物也。</p><p>虞翻曰：乾為聖人，初四易位成既濟。坎為心、為平，故｢聖人感人心而天下和平｣。此保合太和，品物流形也。</p><p>虞翻曰：謂四之初，以離日見天，坎月見地，縣象著明，萬物見離，故天地萬物之情可見也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：山上有澤，鹹。君子以虛受人。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>崔憬曰：山高而降，澤下而升。山澤通氣，鹹之象也。</p><p>虞翻曰：君子謂否乾。乾為人，坤為虛，謂坤虛三受上，故以虛受人。艮山在地下為謙，在澤下為虛。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，鹹其拇。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：鹹其拇，志在外也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：拇，足大指也。艮為指。坤為拇，故鹹其拇。失位遠應，之四得正，故志在外。謂四也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，鹹其腓，兇。居吉。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：雖兇居吉，順不害也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>崔憬曰：腓，腳膊。次於拇上，二之象也。得位居中，於五有應，若感應相與，失艮止之禮，故兇。居而承比於三，順止而隨於當禮，故吉也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，鹹其股，執其隨，往咎。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>崔憬曰：股而次於腓，上三之象也。剛而得中，雖欲感上，以居艮極，止而不前，二隨於己，志在所隨，故執其隨。下比二也，而遂感上，則失其正義，故往吝窮也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：鹹其股，亦不處也。志在隨人，所執下也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：巽為股，謂二也。巽為隨，艮為手，故稱執。三應於上，初四已變歷險，故往吝。巽為處女也，男已下女，以艮陽入兌陰，故不處也。凡士與女未用，皆稱處矣。志在於二，故所執下也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，貞吉，悔亡。憧憧往來，朋從爾思。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：失位悔也。應初動得正，故貞吉而悔亡矣。憧憧，懷思慮也。之內為來，之外為往。欲感上，隔五；感初，隔三，故憧憧往來矣。兌為朋，少女也。艮初變之四，坎心為思，故曰朋從爾思也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：貞吉悔亡，未感害也。憧憧往來，未光大也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：坤為害也。今未感坤，初體遯弒父，故曰未感害也。</p><p>虞翻曰：未動之離，故未光大也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，鹹其脢，無悔。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：脢，夾脊肉也。謂四已變，坎為脊，故鹹其脢。得正，故無悔。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：鹹其脢，志末也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>案：末，猶上也。四感於初，三隨其二，五比於上，故鹹其脢。志末者，謂五志感於上也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，鹹其輔頰舌。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：耳目之間稱輔頰。四變為目，坎為耳，兌為口舌。故曰鹹其輔頰舌。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：鹹其輔頰舌，媵口說也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：媵，送也。不得之三，山澤通氣，故媵口說也。</p>',68)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
